search.script:
(() => {
  const anchors = [...document.querySelectorAll('a[href*="offerId"]')].filter(a =>
    /detail\.(m\.)?1688\.com/.test(a.href) || /detail\.1688\.com\/offer/.test(a.href))
  return anchors.slice(0, 8).map(a => {
    let card = a
    while (card && !/search-offer/.test(card.className || '') && card.parentElement) card = card.parentElement
    const titleEl = card.querySelector('.offer-title-row')
    const title = (titleEl ? titleEl.innerText : a.title || '').replace(/\s+/g, ' ').trim()
    const priceMain = card.querySelector('.price-item .text-main')
    const priceDec = card.querySelector('.price-item > div:nth-child(3)')
    const price = (priceMain ? priceMain.innerText.trim() : '') + (priceDec ? priceDec.innerText.trim() : '')
    const allText = (card.innerText || '').replace(/\s+/g, ' ')
    const sales = (allText.match(/[\d.]+万?\+?件/) || [null])[0]
    const href = a.href
    return { title, price, sales, href }
  })
})()

top250.script:
(() => {
  const items = [...document.querySelectorAll('tr.item')].slice(0, 10)
  return items.map(el => {
    const title = el.querySelector('.pl2 a')?.innerText.replace(/\s+/g, ' ').trim() || ''
    const author = el.querySelector('p.pl')?.innerText.trim() || ''
    const rating = el.querySelector('.rating_nums')?.innerText.trim() || ''
    const count = el.querySelector('.star .pl')?.innerText.match(/(\d+)人评价/)?.[1] || ''
    return { title, author, rating, count }
  })
})()

forecast.script:
(() => {
  const ul = [...document.querySelectorAll('ul')].find(u => u.className.includes('t'))
  return [...ul.querySelectorAll('li')].map(li => {
    const winEl = li.querySelector('p.win em')
    const win = (winEl && (winEl.getAttribute('title') || winEl.innerText || '').trim()) || null
    const tem = [...li.querySelectorAll('p.tem span, p.tem i')].map(e => e.innerText.trim()).filter(Boolean)
    return {
      date: (li.querySelector('h1')?.innerText || '').trim(),
      wea: (li.querySelector('p.wea')?.getAttribute('title') || li.querySelector('p.wea')?.innerText || '').trim(),
      tem: tem.join('/'),
      win,
    }
  })
})()
